import math

def is_perfect_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

# Test the range stated in Candidate A (0 <= a, b <= 8)
solutions_in_range = []
for a in range(9):
    for b in range(9):
        LHS = (2**a) * (5**b) + 625
        if is_perfect_square(LHS):
            solutions_in_range.append((a, b))

print(f"Solutions found in range 0 <= a, b <= 8: {solutions_in_range}")
